import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA source for RMSNorm (fp16 input/output, fp32 accumulation)
_cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>

template <int MAX_THREADS>
__global__ void rms_norm_kernel(const half* __restrict__ x,
                                half* __restrict__ y,
                                const int batch,
                                const int num_features,
                                const int rest,
                                const float eps) {
    // each block processes one (batch, rest) pair
    const int outer = blockIdx.x;
    if (outer >= batch * rest) return;

    const int batch_idx = outer / rest;
    const int rest_idx  = outer % rest;

    // pointer to the first feature of this (batch, rest) slice
    const int base = batch_idx * num_features * rest + rest_idx;

    // ---- reduction: sum of squares over feature dimension ----
    float sum = 0.0f;
    for (int f = threadIdx.x; f < num_features; f += blockDim.x) {
        half hv = x[base + f * rest];
        float fv = __half2float(hv);
        sum += fv * fv;
    }

    extern __shared__ float shm[];
    const int lane = threadIdx.x;
    shm[lane] = sum;
    __syncthreads();

    // parallel reduction in shared memory
    for (int offset = blockDim.x / 2; offset > 0; offset >>= 1) {
        if (lane < offset) {
            shm[lane] += shm[lane + offset];
        }
        __syncthreads();
    }

    const float rms = sqrtf(shm[0] / static_cast<float>(num_features) + eps);

    // ---- write normalized values ----
    for (int f = threadIdx.x; f < num_features; f += blockDim.x) {
        half hv = x[base + f * rest];
        float fv = __half2float(hv);
        float norm = fv / rms;
        y[base + f * rest] = __float2half(norm);
    }
}

// Python entry point
torch::Tensor rms_norm_cuda(torch::Tensor x, const float eps) {
    TORCH_CHECK(x.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kHalf, "input must be float16");
    const int batch = x.size(0);
    const int num_features = x.size(1);
    int64_t rest = 1;
    for (int i = 2; i < x.dim(); ++i) {
        rest *= x.size(i);
    }
    TORCH_CHECK(rest <= INT_MAX, "rest dimension too large for int indexing");

    auto y = torch::empty_like(x);
    const int rest_int = static_cast<int>(rest);

    const int threads = std::min(num_features, 1024);
    const dim3 block(threads);
    const dim3 grid(batch * rest_int);
    const size_t shared_mem = threads * sizeof(float);

    // launch kernel (template argument unused but required for compile)
    rms_norm_kernel<1024><<<grid, block, shared_mem>>>(
        reinterpret_cast<const half*>(x.data_ptr()),
        reinterpret_cast<half*>(y.data_ptr()),
        batch,
        num_features,
        rest_int,
        eps
    );

    // check for launch errors
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(std::string("CUDA kernel launch error: ") + cudaGetErrorString(err));
    }
    return y;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("rms_norm_cuda", &rms_norm_cuda, "RMSNorm forward (CUDA, fp16)");
}
'''

# Compile the inline extension
_rmsnorm_ext = load_inline(
    name='rmsnorm_cuda_inline',
    cpp_sources='',
    cuda_sources=_cuda_source,
    functions=['rms_norm_cuda'],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference RMSNorm model using a custom CUDA kernel.
    """
    def __init__(self, num_features: int, eps: float = 1e-5):
        super().__init__()
        self.num_features = num_features
        self.eps = eps

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # ensure contiguous fp16 tensor on CUDA
        if not x.is_cuda:
            x = x.cuda()
        if x.dtype != torch.float16:
            x = x.to(torch.float16)
        x = x.contiguous()
        return _rmsnorm_ext.rms_norm_cuda(x, self.eps)
